def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        if history[0][1] == 'D':
            return 'C' if history[1][1] == 'C' else 'D'
        return 'C'
    if n == 3:
        if history[0][1] == 'D':
            return 'C' if history[2][1] == 'C' else 'D'
        opp_d = sum(1 for h in history if h[1] == 'D')
        if opp_d == 0:
            return 'D'
        return 'C'
    if n >= 99:
        return 'D'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = sum(1 for a in opp if a == 'D')
    if opp_d == 0:
        return 'D'
    for i in range(3, n):
        if me[i] == 'C' and opp[i] == 'D':
            return 'D'
    if opp[0] == 'D':
        if opp[-1] == 'C':
            return 'C'
        else:
            return 'D'
    if opp[-1] == 'C':
        return 'C'
    else:
        return 'D'
